#ifndef ES2_SHELL_GUI_LAYOUT_H
#define ES2_SHELL_GUI_LAYOUT_H

/* The layout table (shell/data/vshell_layout.json) compiled into
 * C (layout_table.h, generated by shell/tools/gen_layout_table.py, numbers
 * only), the generic builder that turns one screen of it into widgets, and
 * the registration table of the screen packages (shell/src/gui/screens.c).
 *
 * Control indices are global over the 22 screens in construction order
 * (vshell_widgets.md section 4.3); es2_ui_layout_screen_of gives a screen's
 * first index, so control "<screen>.NN" is first + NN. */
#include <stdint.h>

#include "es2/shell/gui/widgets.h"

/* Value kinds of arguments and fields (vshell_widgets.md section 4.2). */
enum {
    ES2_UI_REF_NONE,
    ES2_UI_REF_NUMBER,      /* a = value */
    ES2_UI_REF_GLOBAL,      /* a = address of a run-time global (fonts, background, text pointers) */
    ES2_UI_REF_ESTEXT,      /* a = ESTEXT ID */
    ES2_UI_REF_EXE_STRING,  /* a = address of a literal in VSHELL.EXE, b = its length (contents not copied) */
    ES2_UI_REF_DBA,         /* a = layout_files index, b = frame */
    ES2_UI_REF_DBM,         /* a = layout_files index */
    ES2_UI_REF_CODE,        /* a = handler address */
    ES2_UI_REF_FORMULA,     /* a = index of the distinct formula, in the JSON's order */
    ES2_UI_REF_SPRINTF,     /* a = format address, b = the value (squad row numbers) */
    ES2_UI_REF_FILE,        /* a = record offset, b = size | file index << 8 */
    ES2_UI_REF_ESTEXT_FORMULA, /* a = formula index of a run-time ESTEXT ID */
    ES2_UI_REF_DBA_RECORD,  /* a = DBA file index, b = frame from a record: offset | size << 8 | file << 16 */
    ES2_UI_REF_SPRINTF_FORMULA /* a = format address, b = formula index of the run-time value */
};

/* Rectangle edge kinds. */
enum {
    ES2_UI_EDGE_NUMBER,
    ES2_UI_EDGE_DISPLAY_RIGHT,   /* the display root's right edge (639) */
    ES2_UI_EDGE_DISPLAY_BOTTOM,  /* its bottom edge (479) */
    ES2_UI_EDGE_FORMULA,         /* value = formula index (run time) */
    ES2_UI_EDGE_FILE             /* a game-file field (value = record | size << 8 | file << 16) */
};

/* Parents outside the screen's controls. */
#define ES2_UI_LAYOUT_ROOT (-2)
#define ES2_UI_LAYOUT_DISPLAY (-3)

typedef struct es2_ui_layout_ref {
    uint8_t kind;
    int32_t a, b;
} es2_ui_layout_ref;

/* Constructor arguments of a control (vshell_widgets.md section 2.3; 0 / NONE if absent). */
enum { ES2_UI_ARG_FONT, ES2_UI_ARG_BITMAP_NORMAL, ES2_UI_ARG_BITMAP_ACTIVE, ES2_UI_ARG_BITMAP_EXTRA, ES2_UI_ARG_BITMAP };
enum { ES2_UI_ARG_COLOUR, ES2_UI_ARG_ALIGN, ES2_UI_ARG_OPAQUE, ES2_UI_ARG_STYLE, ES2_UI_ARG_TITLE_HEIGHT,
       ES2_UI_ARG_FILL, ES2_UI_ARG_ARG8 };

typedef struct es2_ui_layout_control {
    uint16_t screen;
    uint8_t cls;                  /* es2_ui_class */
    uint8_t after;                /* after construction: 0 hidden, 1 pending, 2 shown */
    int16_t owner;                /* control whose constructor made this one (labels, columns), -1 */
    int16_t parent;               /* control index, ES2_UI_LAYOUT_ROOT or ES2_UI_LAYOUT_DISPLAY */
    uint32_t site, ctor, global;  /* call site, constructor, where the screen keeps it (0: run time) */
    uint32_t handler;             /* effective +0x3d (0: none) */
    int32_t rect[4];
    uint8_t rect_kind[4];
    int32_t screen_rect[4];
    uint8_t has_screen_rect;
    uint8_t per_record;           /* 1 or 2: template of a gam\arm_weap.dat record list (vshell_widgets.md 4.4) */
    es2_ui_layout_ref text;       /* label / text argument (or the text set after construction) */
    es2_ui_layout_ref ref[5];     /* ES2_UI_ARG_FONT ... ES2_UI_ARG_BITMAP */
    int32_t num[7];               /* ES2_UI_ARG_COLOUR ... ES2_UI_ARG_ARG8 */
    uint16_t field_first, field_count;
    uint16_t method_first, method_count;
    uint16_t show_hide_first, show_hide_count;
} es2_ui_layout_control;

typedef struct es2_ui_layout_field {
    uint16_t offset;              /* VSHELL object offset (+0x49, +0xb5, ...) */
    uint8_t size;
    es2_ui_layout_ref value;
} es2_ui_layout_field;

enum { ES2_UI_METHOD_QUAD_COLUMNS = 1, ES2_UI_METHOD_QUAD_SET_COLOUR, ES2_UI_METHOD_ANIM_ADD_FRAME };
typedef struct es2_ui_layout_method {
    uint8_t kind;
    uint32_t site;
    es2_ui_layout_ref ref[5];     /* columns: font, text0..3; frame: the bitmap */
    int32_t num[8];               /* columns: align0..3, x1..x3, unused; colour: column, colour */
} es2_ui_layout_method;

typedef struct es2_ui_layout_show_hide {
    uint8_t show;                 /* 1 show, 0 hide */
    uint32_t site;
} es2_ui_layout_show_hide;

typedef struct es2_ui_layout_screen {
    uint32_t constructor;
    uint16_t first, count;
} es2_ui_layout_screen;

#include "es2/shell/gui/layout_table.h"

const es2_ui_layout_screen *es2_ui_layout_screen_of(int screen);
const es2_ui_layout_control *es2_ui_layout_control_of(int index);
const es2_ui_layout_field *es2_ui_layout_field_of(int index);
const es2_ui_layout_method *es2_ui_layout_method_of(int index);
const es2_ui_layout_show_hide *es2_ui_layout_show_hide_of(int index);
const char *es2_ui_layout_file(int index);

/* What a screen package supplies to the builder: the resources the table
 * names by reference (all may return NULL), and the handlers by VSHELL
 * address. */
typedef struct es2_ui_resolver {
    void *context;
    const es2_dfn *(*font)(void *context, uint32_t global);            /* 0x46ddfc, 0x46de00, 0x46de04 */
    const es2_bitmap *(*bitmap)(void *context, const es2_ui_layout_ref *ref); /* DBA frame, DBM, global */
    /* The text of a label argument (ESTEXT ID, executable literal, global,
     * sprintf row number); NULL = empty. */
    const char *(*text)(void *context, const es2_ui_layout_ref *ref);
    es2_ui_handler (*handler)(void *context, uint32_t address);
} es2_ui_resolver;

/* Builds screen `screen` under the toolkit's (hidden) roots: every control
 * that is not created by its owner, in construction order, with its class's
 * constructor and arguments and the methods (ESQuad columns and colours,
 * ESAnim2 frames); then the fields the screen constructor wrote (+0x3d,
 * +0x49, +0x4d, +0x51, +0x55..+0x71, +0x9f, +0xb3..+0xc5, +0x6e5, +0x6e6)
 * and the table's after_construction state (hidden or pending). ids[k] receives
 * the window of control first + k (0 for template controls of record lists
 * and unresolved rectangles, which the screen builds itself). Returns the
 * number of windows built, -1 for a bad screen or argument. Fields whose
 * value is a run-time formula are left to the screen. */
int es2_ui_layout_build(es2_ui *ui, int screen, const es2_ui_resolver *resolver, es2_ui_id *ids, int capacity);

/* ---- registration table (shell/src/gui/screens.c) ----------------------- */
typedef struct es2_ui_screen_entry {
    int screen;                                    /* ES2_UI_SCREEN_* */
    int (*build)(es2_ui *ui, void *context);       /* the screen's constructor (0 = success) */
} es2_ui_screen_entry;

/* The registered screens, terminated by an entry with build == NULL. */
extern const es2_ui_screen_entry es2_ui_screens[];
/* The registered entry of a screen, NULL if none. */
const es2_ui_screen_entry *es2_ui_screen_find(int screen);

#endif
